INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('Ultimate R2x','experiment/drnas-ultimate-r2x-20261107','ULTIMATE_R2_SOURCE_PAIRED_AUDIT_PASS_NOT_GLOBAL_BLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42348940571','200 paired attempts completed. R153 14/40 PAR2 1378.713012; R2x clean 18/40 1166.599241; R2x live 18/40 1169.270087. Clean beats Live. Live selected 6, all missing terminal native result (timeout).') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('Ultimate T Phase1','experiment/drnas-ultimate-t-trail-frontier-20261107','IN_PROGRESS_PREPARE_PASS_5_SHARDS_RUNNING','https://github.com/Frane12/AndroidGameTest/actions/runs/42351079758','240 paired attempts planned 6 native modes 20 same original R2 CNFs 2 reps; no final numbers until audit; not blind.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('R194 External Replay','experiment/drnas-r194-artifact-audit-recovery-20261107','R194_SEED_REPLAY_AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42351373958','96 completed attempts 4 methods x24 on one originally seen external SAT CNF, 12 seeds 2 orders, artifact-only final audit restored.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2X_FINAL_NO_LIVE_GAIN','AUDIT_CONFIRMED','R2x clean solves 18/40 with PAR2 1166.599241, Live solves 18/40 with PAR2 1169.270087 on exactly same original 20-CNF source cohort.','ultimate_r2x_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42348940571','No general GF2->CDCL speedup, same previous nonblind cohort; six eligible Live cases timeout, terminal native counters absent.','T true shadow, certified source-only frontier, delivered-reason telemetry with independent unseen sources.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2X_MISSING_NATIVE_TERMINAL','AUDIT_LIMITED','R2x Live selected certified mode 6 times but all six were timeout and had no terminal native result; reported delivered_reasons 0 is missing evidence, not proof none happened.','ultimate_r2x_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42348940571','Live selected != live observed. Need periodic native progress and explicit started mode.','T progress probe plus true shadow and started-mode telemetry.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R194_REPRODUCIBLE_SINGLE_CASE','AUDIT_CONFIRMED','On 1 original external SAT formula with 12 seeds and 2 orders, R194 dual_keep_default solves 6/24 (PAR2 1139.035484) vs default 0/24 (1440); 96 attempts across four arms audited.','r194_external_seed_recovered','https://github.com/Frane12/AndroidGameTest/actions/runs/42351373958','Not blind, just 1 formula; changing seed/order alone does not demonstrate multi-family generalization.','Use a new SHA-disjoint SAT original holdout with dual_keep_default vs clean and same seed/order.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T_EXTENDED_RESOLUTION_INPROCESSING','HYPOTHESIS','SAT 2026 Factoring Learned Clauses suggests source-only XOR detection could miss useful parity/ITE structure that arises later within CDCL learned clauses.','ultimate_r2x_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42348940571','The literature reports a separate solver design and does not validate an unimplemented DRNAS technique.','After phase1, test proof-checked XOR/ITE learned-clause factoring as an isolated ablation with no edit to original CNF.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('ultimate_t_phase1_20261107','Ultimate T phase1','frozen_original_and_synthetic_not_blind',42351079758,20,240,'ULTIMATE_T_PHASE1_AUDIT_PASS_NONBLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42351079758','Source original 20 R2 same manifest 2e6169009e985555e43e81d9b534f3bb307cef93963329694ef42459bef3c2e2, reused NOT blind. 6 arms 2 reps; Source/Shadow >82M row update events each; no Source delivered reasons; Derived 108 proposals and 40 completed reasons only development.') ON CONFLICT(cohort_id) DO UPDATE SET version=excluded.version,cohort_type=excluded.cohort_type,github_run_id=excluded.github_run_id,original_formulas=excluded.original_formulas,total_attempts=excluded.total_attempts,audit_status=excluded.audit_status,source_url=excluded.source_url,notes=excluded.notes;
