INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('Ultimate T2','experiment/drnas-ultimate-t2-causal-isolation-20261107','FINAL_AUDIT_PASS_NOT_BLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','2026-11-07: 5/5 shards; 400/400; R153 14/40 PAR2 1390.198323; Clean 16/40 1240.368493; Adaptive 16/40 1239.196534; Derived incremental 16/40 1242.885956 with 106555192 row events and 40 completed reasons in development, none in new_to_r1. No demonstrated causal GF2 gain.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T2_DERIVED_ROWS_NO_AGGREGATE_GAIN','AUDIT_CONFIRMED','T2 derived incremental: 16/40 PAR2 1242.885956 vs clean 16/40 PAR2 1240.368493, loss 2.517463s; 106555192 incremental row events, 108 proposals and 40 completed reasons restricted to development, zero completed reasons on new_to_r1. T2 adaptive 16/40 PAR2 1239.196534 (1.171959s within-run gain vs clean).','ultimate_t2_phase2_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','20 original sources reused from R2; not blind. Some selected timeout terminal counters missing; no independent LRAT for native UNSAT. Tiny aggregate gains can be noise; no universal SAT advantage.','TD: isolate lazy two-watch source-row update from eager 69M events on unchanged 20-CNF corpus, then unseen originals if effect replicates; matched clean/shadow, native selftests and source SHA audit.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES
('td_exact_bucket_diagnostic_20261107','TD exact bucket source-XOR diagnostic','detector_only_nonblind',42356263207,20,0,'DETECTOR_AUDIT_PASS_NO_SOLVER_BENCHMARK','https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','Same unchanged T2 20 source SHA manifest; old streaming hit present on 8 source cases; exact scan 11912 distinct source-variable/parity matched patterns; no newly detected source case; old scan cumulative 0.402115 s, partition scan 6.599585 s; zero inconclusive cases; solver unchanged and SAT PAR2 unmeasured.')
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES
('TD exact bucket diagnostic','experiment/drnas-td-exact-bucket-probe-20261107','DETECTION_ONLY_AUDIT_PASS_NO_SPEEDUP_CLAIM','https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','20 frozen original SHA, old detector hit 8 source cases, exact scan 11912 matched patterns, 0 new source cases, 0 inconclusive; old detection 0.402115 s vs exact 6.599585 s; no SAT runs, no independent UNSAT proof, no measured solver PAR2.')
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES
('TD_BUCKET_EXACT_NO_NEW_SOURCE_COVERAGE','AUDIT_LIMITED','On 20 frozen T2 original source SHA, complete bucket scan found 11912 exact parity-group patterns but discovered 0 previously undetected source cases beyond the 8 already flagged by cheap streaming; total detection time 6.599585 s vs 0.402115 s. This is NOT a solver speedup.','td_exact_bucket_diagnostic_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356263207','Patterns and sources are different units; many patterns may be redundant. No CDCL integration, SAT/UNSAT causal run, new independent source family or UNSAT proof. Times compare detector scans, not solver runtimes.','Do not promote bucket scan into solver. First measure canonical independent parity rank, residual-CNF linkage, source replay and novel reason delivery versus clean/shadow; then source-disjoint capped trials.')
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('ultimate_ta_disjoint_20261107','Ultimate TA source-disjoint structural holdout','original_SHA_disjoint_R1_R2_R193_not_global_blind',42353551967,30,300,'TA_30_ORIGINAL_SHA_DISJOINT_AUDIT_PASS_NOT_GLOBAL_BLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42353551967','6/6 shard PASS; final 300/300 audit, paired same-source 60 blocks; source disjoint from R1/R2/R193 manifests only; 52 portfolio R1A routes, 8 clean; SAT witnesses checked unchanged original CNF; no independent LRAT for native UNSAT.') ON CONFLICT(cohort_id) DO UPDATE SET version=excluded.version,cohort_type=excluded.cohort_type,github_run_id=excluded.github_run_id,original_formulas=excluded.original_formulas,total_attempts=excluded.total_attempts,audit_status=excluded.audit_status,source_url=excluded.source_url,notes=excluded.notes;
