INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('TD2 bounded sparse GF2 640 development','experiment/drnas-td2-sparse-budget-20261107','TD2_AUDIT_PASS_NONBLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42393873346','40 frozen R199 originals same SHA reused development, 2 reps, 8 arms, 20s cap inclusive SAT witness; prep cap 0.8s pilot cap 25ms. Kissat sparse 24/80 PAR2 2304.872815 versus plain 23/80 2360.573490, hybrid 24/80 2311.233685; CMS sparse 20/80 2469.159979 versus plain 20/80 2462.314716. 14/80 prep abstentions for each sparse variant. All source GF2 certified, generic backend UNSAT independent LRAT absent. Do not label independent holdout.') ON CONFLICT(version) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R199_GAIN_XOR_CONCENTRATION','AUDIT_CONFIRMED','R199 Kissat R28 36/120 and PAR2 3440.828233 vs plain Kissat 33/120 and 3560.914758: 119.907267s of 120.086525s aggregate gain (99.85%) occurs only in xor_crypto source cohort; 21 paired losses 13 wins 86 ties.','r199_mixed40_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42390697619','20s cap, 40 real originals, frozen R199 originals reused in TD2; no universally validated route label.','Pre-register a safe source-only low-cost XOR gate, evaluate with abstention against always-R28/plain Kissat on novel SHA/family-disjoint originals.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD2_SPARSE_REUSED_POSITIVE_KISSAT_NEGATIVE_CMS','AUDIT_CONFIRMED','TD2 sparse Kissat 24/80 PAR2 2304.872815 vs plain Kissat 23/80 PAR2 2360.573490 (55.700675s gain) and CMS sparse 20/80 PAR2 2469.159979 vs CMS plain 20/80 PAR2 2462.314716 (6.845263s regression). TD2 pilot Kissat 24/80 PAR2 2305.727933, no advantage over sparse alone.','td2_sparse_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42393873346','R199 same SHA development originals, not blind; 0.8s prep cap and 25ms pilot charged; independent backend UNSAT LRAT absent.','No automatic promotion; compare frozen sparse gating on 40+ distinct new original SHA, paired plain/hybrid/sparse/clean/shadow, stratify by family and per-source delta.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD2_CMS_FAMILY_HARM','AUDIT_CONFIRMED','In TD2 industrial_planning CMS sparse 4/20 vs plain 6/20 and -61.055359s PAR2 change; CMS sparse hardware_software 4/20 vs plain 2/20 and +55.784198s. Aggregate CMS sparse loses.','td2_sparse_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42393873346','Family-specific outcomes may be driven by few sources and are not proof of category-based route correctness; code must never memorize source SHA.','Investigate source-only measures predicting beneficial certified Gaussian implication (e.g. XOR-CNF overlap) with independent family/source disjoint holdout.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TA4_PILOT_GAIN_NOT_TRANSFER','AUDIT_CONFIRMED','TA4 8/30 PAR2 962.587782 versus TA3 portfolio 8/30 PAR2 963.287414, a 0.699632s negligible paired improvement from an up-to-256-conflict early diagnostic.','ta4_sat2025_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42395771235','15 source-disjoint SAT2025 originals, only 2 reps each; generic UNSAT LRAT missing.','Do not spend 0.28s early pilot by default; test cheaper verified source-only gate and compare against matched shadow.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TK_PLANTED_REASONS_ZERO','AUDIT_CONFIRMED','TK planted XOR benchmark 36/36 solved all arms; Clean PAR2 1.575181, Shadow 1.722849, Live cooldown 1.740688, proposals and native reasons both zero.','tk_mixed_planted_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42391271033','Synthetic deterministic planted SAT not real independent mixed-SAT holdout.','Instrument propagation-consumed reasons and conflict causal impact; suppress inactive overhead.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('ta6_sat2026_576_20261107','TA6 prospective guarded R28 selector 576','official_sat2026_SHA_disjoint_known_exclusions_not_global_blind',42409355073,24,576,'TA6_AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42409355073','24 SHA-disjoint original SAT2026 CNFs x3 reps x8 arms, 20s cap, source-only selector precommitted. 6 solved TA3 vs 3 guarded; TA6 guarded PAR2 2765.599920 vs TA3 2673.263775 (92.336145s regression). 3 losses on one SAT original where CMS solved 9.2s, TA6 rerouted to Kissat R28 timeout. No independent native UNSAT LRAT; all SAT original witness verified. Negative, do not promote.') ON CONFLICT(cohort_id) DO NOTHING;
