INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('TA6 prospective guarded R28 selector 576','experiment/drnas-ta6-confidence-router-20261107','TA6_AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42409355073','24 SHA-disjoint original SAT2026 CNFs x3 reps x8 arms, 20s cap, source-only selector precommitted. 6 solved TA3 vs 3 guarded; TA6 guarded PAR2 2765.599920 vs TA3 2673.263775 (92.336145s regression). 3 losses on one SAT original where CMS solved 9.2s, TA6 rerouted to Kissat R28 timeout. No independent native UNSAT LRAT; all SAT original witness verified. Negative, do not promote.') ON CONFLICT(version) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_LAZY_ZERO_EVENT_NO_CAUSAL_GAIN','AUDIT_CONFIRMED','TD lazy-source avoids 72,868,484 t_source frontier update events but no measurable advantage: td_lazy_source 16/40 PAR2 1235.895448 vs t_source 16/40 1235.887583; 0 proposals and completed reasons. T Shadow 16/40 PAR2 1235.933106. Native terminal_missing 8.','ultimate_td_lazy_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356438634','Same frozen 20 originals as T2; development not blind. Event counter reduction does not prove wall time saving; no independent native UNSAT LRAT.','Require proof-gated reason delivery and causal propagation-consumed telemetry on new original SHA, matched clean and true shadow.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TA6_GUARDED_SELECTOR_CROSSBACKEND_HARM','AUDIT_CONFIRMED','TA6 guarded selector on 24 new SHA-disjoint SAT2026 originals: 3/72 solved PAR2 2765.599920 vs precommitted TA3 6/72 PAR2 2673.263775, -92.336145s, 4 paired losses 2 wins 66 ties. A source parity signal switched CMS (~9.2s SAT) to Kissat R28 (20s timeout) for 3 repeats of one original.','ta6_sat2026_576_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42409355073','Precommitted selector, not global blind; same source repeated 3 times, so 3 losses are one source-cluster; independent UNSAT LRAT missing.','Separate GF2 activation from backend switching; fail-closed preserve CMS selection unless independently validated out-of-sample cross-backend advantage; new SHA-disjoint prospective test.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R200_PROSPECTIVE_ALL_TIMEOUT','AUDIT_CONFIRMED','R200 24 original SAT2026 CNFs 216 paired, all 3 CMS arms 0/72 solved and PAR2 4320s. Hybrid injected 1152 certified clauses and 42.151122s preprocessing across 72 attempts; no outcome benefit.','r200_prospective_cms_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42403144676','60s censoring, source SHA disjoint known exclusion, not global blind; PAR2 tie does not imply equal progress.','Run bounded longer cap only on frozen unsolved originals with instrumented conflicts and source certification, no SOTA claim.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R201_STAGED_SMALL_UNVERIFIED_UNSAT','AUDIT_CONFIRMED','R201 32 trials on preexposed R194 originals, stage 4/8 PAR2 121.483661 vs plain 4/8 122.588972, shadow 4/8 125.255473, static 4/8 126.754795. 64 source rows injected in staged, no proven runtime callback, 1.11896s prep.','r201_staged_cms_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42403760957','Only 4 originals x2 reps, all solved UNSAT unverified independent LRAT; cannot infer staged improvement transferable.','Run genuinely source-disjoint originals and verify UNSAT independently before claims; add stage/no-stage ablation with same resource budget.') ON CONFLICT(finding_id) DO NOTHING;
