INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('T6A_CHEAPER_CERT_BUT_STILL_BELOW_CLEAN','AUDIT_CONFIRMED','T6A 240/240: cap 0.40s reduces total Active GF2 preparation 7.512506 to 4.142488s; T6A Active 16/40 PAR2 1242.088566 vs T5 Active 1243.585171, BUT Clean 16/40 PAR2 1240.933749. Active vs Shadow -0.158597s, 114 proposals and 48 completed reasons no solved gain.','t6a_240_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42485138094','Same previously-used 20 frozen originals (not blind); no independent native UNSAT LRAT; reason count not causal proof.','Follow existing cost feedback experiments; demand active vs true shadow wins on disjoint original SHA and instrumented native impact before promotion.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('CRR1B3_DEDUPE_WITHOUT_END_TO_END_GAIN','AUDIT_CONFIRMED','CRR1B3 36/36 original source-paired: all three arms 0/12 solved PAR2 1440s; B2 injected 54 clauses x3 on one formula; B3 rejected all 54 as no cross-CNF relevance, 0 added; filter adds CPU overhead.','crr1b3_36_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42489602695','Posthoc four-source cohort; 60s all-timeout censoring; no measurable speed gain and 0 correct finishes.','Use O(1) early abstain on zero candidates, validate overhead only; defer further experiments until new cost or novelty hypothesis.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE4_P1_ACTIVE_NO_SHADOW_GAIN','AUDIT_CONFIRMED','MRE4 P1 320/320: active 52/64 PAR2 766.227979, shadow 52/64 PAR2 765.993212, CMS native 52/64 PAR2 769.673764; R28 safe 52/64 PAR2 752.694149. 20 active lemmas on reused synthetic controls.','mre4p1_320_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42488708574','Not blind; SAT witness verified, native UNSAT LRAT absent; no per-reason source instrumented native hooks in P1.','Use P2 native watched-reason diagnostics, demand active vs same-prep shadow on new original SAT2026 source-disjoint cohort.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE4_P2_WATCHED_UNIT_ONLY_SYNTHETIC','AUDIT_CONFIRMED','MRE4 P2 320/320: 20 active lemmas and 68 tagged native nonroot unit events; all 68 only reused synthetic controls, zero tagged on reused official2026 and new-mixed cohorts. Active 52/64 PAR2 769.493501 vs Shadow 769.377473; no causal advantage.','mre4p2_320_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42490307382','No evidence tagged events imply counterfactual UNIQUE new implications; independent native UNSAT LRAT absent; development/nonblind.','Measure novelty relative to same-trail CNF BCP and CPU; activate only proven nonredundant reason with bounded cost on fresh source SHA.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE5_NATIVE_WATCH_EVENTS_ARE_NOT_UTILITY','AUDIT_LIMITED','MRE5 32 CPU measurements on one reused official CNF with 2 seeds x2: XOR trace-off total CPU 31.343673s; A 32.049424s; B 33.325243s; A+B 31.294509s. Native tagged unit events on instrumented paths do not ensure CPU win.','mre5_cpu32_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42490090624','Only one original; precomputed certified lemma cost excluded; telemetry overhead varies; independent UNSAT LRAT absent, cannot infer general solver PAR2.','Extend candidate utility assessment only if existing MRE6 active CPU feedback bench yields source-diverse, same-prep shadow and controls.') ON CONFLICT DO NOTHING;
