INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE4_P2_REPEAT_SIGN_FLIP_0_301S','AUDIT_CONFIRMED','Repeated MRE4 P2 source-paired 320/320 PASS: Active 52/64 PAR2 769.807407 vs Shadow 52/64 PAR2 770.108722 (0.301315 s lower), whereas prior run Active 769.493501 vs Shadow 769.377473 (0.116028 s higher). Both runs exactly 20 active lemmas and 68 tagged nonroot units entirely synthetic; zero tagged on reused official SAT2026. No solved count difference.','mre4p2_repeat_320_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42490535801','Repeat used a one-line header include-path fix, and run-level timing sign flipped; samples are not independent fresh SHA; UNSAT LRAT absent. Timing difference does not establish utility.','Continue active vs same-prep shadow on unseen genuine mixed originals with counterfactual CNF BCP novelty, not further rerun this frozen cohort.') ON CONFLICT DO NOTHING;
