INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE6_SINGLE_SOURCE_FRESH_SEED_EQUIV_CPU_SIGNAL','AUDIT_LIMITED','MRE6 84/84 PASS, one reused SAT2026 CNF, 4 fresh seeds: XOR baseline mean native solve CPU 7.853078 s; certified BOTH equivalence as lemmas 7.009366 s and quotient_no_xor 7.103095 s, each 4/4 fresh seed wins; quotient with source XOR import 8.328338 s (0/4 wins), A 8.487026 s, B 7.949169 s. All SAT witnesses reconstructed/checked. Frozen pre-seed online policy remained XOR; no promotion.','mre6_cpu_84_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42491590558','CPU solve only: GF2 certification, preparation, replay cost excluded; single previously-used original; no source/family holdout or paired PAR2; native UNSAT LRAT not covered; small apparent margins may depend on source.','Pre-register >=3 source/family-disjoint original CNFs (prefer >=20), >=3 fresh seeds per source; same-CPU and prep-charged 7-arm pair, include unchanged CNF xor and true same-prep shadow; independent SAT witness and UNSAT proof if claimed. Reject if quotient+or-without-XOR fails net CPU/PAR2 or causes regressions.') ON CONFLICT DO NOTHING;
