INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE6B_NEW7_ALL_TIMEOUT_2_OF7_ELIGIBLE','AUDIT_CONFIRMED','Seven source-disjoint originals from declared MRE2-MRE6 registries (4 official SAT, 3 official UNSAT); four methods 0/14 solved PAR2 504 each at 18s cap, 56/56 attempts. Replay-certified quotient eligibility only 2/7; quotient CNF 22688 -> 22685 and 11072 ->11070; extra quotient prep 9.012464s over 14 vs native 0.626016s. No PAR2 advantage; no rollout.','mre6b_seven_unseen_56_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42495311707','Not globally blind historical registry; no independent UNSAT LRAT; all-timeout cap masks CDCL progress; source labels official SAT/UNSAT are NOT newly proved verdicts.','Pre-register broader mixed SAT+UNSAT original source SHA, cheap binary equivalence screen, require meaningful quotient size/value and full prep-charged paired PAR2; avoid further calibration on frozen 7.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE4P3_REDUCTION_SHADOW_NO_WIN','AUDIT_CONFIRMED','MRE4 P3 Q1 480/480: all six modes 68/80 solved. Safe R28 PAR2 761.014665; quotient-no-XOR 782.968832, quotient+XOR 782.950781, same-prep shadow 782.966365, CMS-native 782.178142. Quotient 22 eliminated var-events and 86 clause-events in 80 attempts, no solved gain. Of real official reused sources quotient activated zero times.','mre4p3_quotient_480_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42494099280','Mixed reused development and synthetic, not blind; 30s cap, SAT models verified but UNSAT LRAT absent; tiny differences near measurement noise.','Prioritize structural eligibility and quotient size under very low cost, not promotion; fresh source-diverse holdout with clean/shadow/R28.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('CRR1B4_MARGINAL_PROPAGATION_NO_PAR2','AUDIT_CONFIRMED','CRR1 B4 48/48 90s, four original source SHA; Kissat, B3 loose8, B4 value8 and B4 value16 each 0/12 solved PAR2 2160. One source supports 8 or 16 new CNF BCP marginal units per repeated trial (initial 108 candidate unit signals), yet zero solver improvement.','crr1b4_48_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42493774624','Posthoc four-source cohort; all timeouts, native reason consumption not proved; BCP probe is not end-to-end CDCL utility.','Stop expanding batch size on same sources. Test exact runtime CDCL novelty/interaction and safety guard only on fresh source-disjoint formulas.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('CRR1B3LOOSE_DYNAMIC_LEMMAS_ALL_TIMEOUT','AUDIT_CONFIRMED','CRR1 B3L 48/48 source-paired, 60s: all arms 0/12 solved PAR2 1440. B2 162 repeated additions, loose8 24, loose16 48, Kissat 0; no solved gain.','crr1b3loose_48_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42491257874','Same posthoc 4 source SHA and all timeout, no confirmation larger candidate budget helps.','Keep cheap zero-candidate abstain; don''t resubmit larger duplicate B3 variants absent new causal signal.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE6B_FACTORIAL_SINGLE_SOURCE_INTERACTION','AUDIT_LIMITED','Reused one-original 4-seed 2x2 MRE6b CPU interaction audit 48: quotient_no_xor vs native-no-xor CPU benefit mean 1.953444s; quotient with XOR vs XOR baseline benefit mean -0.299652s; interaction mean -2.253096s. Both from same previously used source, solve CPU excluding proof/rewrite and no PAR2.','mre6b_factorial_cpu_48_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42492372821','Not source-blind; seeds reused from MRE6; time excludes certification/rewrite. Different baseline XOR vs no-XOR must not be conflated.','Treat MRE6b 7-new-source 0/14 as external check; research source-diverse formula rewriting with certified CNF equivalence and full CPU charge only after finding strongly compressible sources.') ON CONFLICT DO NOTHING;
