INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE6C_DIRECT_EQ_PROJECTED_LARGE','AUDIT_LIMITED','MRE6c exact positive CNF binary equality screen: original SHA fdae904ea92d7ec0c8c53d82ce826395c69826bfc00419e4e21bb72d80ce434b has 672 independent merges, mapped occurrences 5088, projected literals 30336 to 27648, projected clauses 11072 to 9728 (1344 tautologies), median screen 0.036508s; no solve test and quotient output must be certified/replayed.','mre6c_eq_screen_7_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42496369782','Projected structural reduction is not a measured solving gain; already-used 7-source cohort and no independent UNSAT LRAT.','Use cheap fail-closed binary equivalence screen as candidate; test certified all-class quotient vs same-prep shadow and native on source-disjoint originals, with full preprocessing charge and real solved PAR2.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE6D_90S_ALL_TIMEOUT','AUDIT_CONFIRMED','MRE6d 56 source-paired 90-second attempts on 7 reused official SAT2026 originals: 0/14 solved each, PAR2 2520 for all four arms (native-no-XOR; all-no-XOR; all-XOR; one-quotient-no-XOR). More equalities as currently implemented did NOT flip a timeout.','mre6d_90s_56_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42496742982','Official labels SAT4 UNSAT3; no independent UNSAT LRAT; reused sources, no solved finish; exact CDCL progress not tracked at timeout.','Use bounded conflicts paired counter telemetry first, then future real solving test with larger compressions on different source SHA.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE6E_ALL_BUDGET_UNKNOWN','AUDIT_CONFIRMED','MRE6e 56 paired fixed 1000/5000 conflict-budget probes on 7 frozen originals had zero verified solved outcomes. With 1000 conflicts median decisions native 1699 and quotient-no-XOR 1699; with 5000 conflicts native median 7258 and quotient-no-XOR 7258. Quotient adds preprocessing; pseudo-PAR2 in diagnostic report must not be used as solving PAR2.','mre6e_bounded_56_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42499473274','Same already exposed development source SHA; no independent UNSAT LRAT; conflict-BUDGET is neither SAT nor UNSAT result.','Source-stratify by equality density, inspect MRE6f causal counter repeats and require real solve performance under fixed wall budget for promotion.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE6F_672_EQ_35PCT_PROP_REDUCTION','AUDIT_LIMITED','MRE6f 72 bounded posthoc trials. On source SHA fdae904ea92d7ec0c8c53d82ce826395c69826bfc00419e4e21bb72d80ce434b with 672 certified direct CNF equality merges, all-class quotient reduced CNF clauses 11072 to 9728 and propagations 35.08737% at 5000 conflicts; geomean full wall speedup including prep 1.208918x across 3 seeds (all 3 win), but at 1000 conflicts full wall 0.947483x (net slowdown). Small equality source with 4 merges gives 0.500710x full wall at 5000; zero-equality control 0.987090x. Neither condition proves PAR2 or solves.','mre6f_72_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42499854392','Posthoc selected same known source SHA; fixed conflict budget 1000/5000 ends BUDGET without SAT/UNSAT; all original source SHA/seed pairs; independent UNSAT LRAT absent.','Pre-register cheap source-only equality class size and projected CNF reduction thresholds on separate development; then freeze and evaluate CPU/prep and solved/PAR2 with true native and same-prep shadow on new official mixed sources.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('CRR1B5_PROFILE_DIFFERENT_ONLY','AUDIT_LIMITED','CRR1B5 12 discrimination-only original W4 diagnostics: top8 selection differs by 5,2,5 candidates across three seeds 101/202/303, but no solver benchmark, verified SAT/UNSAT results or PAR2 in this run.','crr1b5_context_12_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42495990059','Only score diversification, not solution speed; posthoc reused four source SHA.','Compare actual native reason utility rather than more candidate scores; use short real solvable benchmark.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('CRR1B6_NO_CONF_BENEFIT','AUDIT_CONFIRMED','CRR1B6 72 fixed-conflict probes all stopped at 500, 5000 or 25000 conflicts. Median native CDCL stats nearly identical to Kissat plain; B5 preprocessing around 0.25s vs Kissat ~0.03s, and no verified solved attempts. No solving PAR2 should be claimed.','crr1b6_conflict_72_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42497644725','No solving outcome, posthoc same four original sources; fixed budget CPU throughput is NOT end-to-end solved comparison.','Require new-to-benchmark solvable official examples and same-source control; reject if no solved/PAR2 improvement.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('CRR1B7_W4_EASY_NO_GAIN','AUDIT_CONFIRMED','CRR1B7 36/36 solved under 6s on 2 official easy original W4 and 2 synthetic XOR controls. Official (6 per arm) Kissat PAR2 12.234679, B3 loose8 13.427797, B5 multi8 13.286767. Synthetic (6 per arm) Kissat 0.307667, B3 0.316316, B5 0.315533. No total PAR2 gain from bridge.','crr1b7_easy_36_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42498950668','Posthoc reused official sources and synthetic examples separate. Very small corpus; no globally blind validation.','Do not deploy B5; seek a causal impact signal on genuinely mixed original CNFs with nonzero successful native implications.') ON CONFLICT DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('CRR1B7B_EASY_REPEAT_NO_GAIN','AUDIT_CONFIRMED','CRR1B7b repeated same type easy 36/36 solved: official W4 (6 per arm) Kissat 12.832201, B3 13.903090, B5 13.785200; synthetic XOR (6 per arm) Kissat 0.340851, B3 0.504229, B5 0.581152. Neither B3 nor B5 beats baseline in official or synthetic cohort.','crr1b7b_easy_36_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42499333218','New repeat but same previously studied source groups; do not infer broad effect from small synthetic samples.','Stop repeating same B7 arms; test a new mathematically differentiated hypothesis or a source-disjoint holdout.') ON CONFLICT DO NOTHING;
