INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('CRR1B8_TA3_NO_MEDIUM_ELIGIBLE','AUDIT_CONFIRMED','B8 scout 24 reused SAT2025 TA3 originals at 5s: 0 medium certified GF2 eligible. One fallback hgen original SHA b15bdf2acd29a6a149b96135c7d098e375600370ef63eefc22cdbe43b7d8eaa1 tested 2 reps x3 modes at 6s: all six SAT original witnesses verified; Kissat PAR2 3.677523, B3 3.691680, B5 3.681638, no injected lemmas. Failed run 42500065378 due DIMACS bounds; corrected final 42500265299 PASS all shards and audit.','crr1b8_ta3_scout_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42500265299','No medium eligible formulas, no 24-original paired solved benchmark, earlier CRR scout UNSAT unverified DRAT timeout must remain unverified; posthoc one source.','Stop this unproductive scout; seek precommitted source-disjoint originals with provable XOR-CNF bridge novelty, compare native control and true shadow before promotion.') ON CONFLICT DO NOTHING;
