INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE7_4NEW_35S_6OF8_VS_CMS4OF8','AUDIT_LIMITED','MRE7 medium original SAT2026 reference-selected NEW sources 4 x 2 reps x 35s; MRE7 CPU guard solved 6/8 PAR2 225.106641, CMS-native 4/8 PAR2 308.295923, CMS-source-XOR 5/8 PAR2 272.424408, MRE6b quotient 5/8 274.525456. Reused 2 anchors: all arms 4/4, MRE7 25.698476 vs CMS-native 28.256027. SAT models original checked; official UNSAT crosscheck only. MRE7 new-source gates FALLBACK_CMS_XOR not direct quotient, so benefit is NOT evidence active equivalence elimination.','mre7_medium_48_20261108',42500214333,'Only FOUR new reference-time filtered official sources and 2 reused anchors, historical registry not exhaustive; MRE7 new routes fall back to CMS XOR and short sample may exhibit stochastic variance; no LRAT. No global 27% claim.','Already-running prospective MRE7 2024+2025 reference-only 20+ source 8s source-paired CMS/quotient/gate/Kissat: freeze 42501143598 and benchmark 42501527378. Avoid duplication; wait for blind source-audited paired PAR2; then if justified extend to 30-50 new sources with CaDiCaL and more seeds.') ON CONFLICT DO NOTHING;
