-- DRNAS SAT: cumulative verified history to 2026-11-07; T2, TA, TD lazy, TA6 final audited.
-- IZVORI: verified GitHub Actions FINAL audit logs. PAR-2 sums are comparable ONLY within the same cohort_id.
-- Censored timeout times are NOT finite speedups; use solved count + within-cohort PAR2. No external competition ranking claimed.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS benchmark_cohorts (cohort_id TEXT PRIMARY KEY, version TEXT NOT NULL, cohort_type TEXT NOT NULL, github_run_id INTEGER NOT NULL UNIQUE, original_formulas INTEGER, total_attempts INTEGER, audit_status TEXT NOT NULL, source_url TEXT NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS benchmark_modes (cohort_id TEXT NOT NULL REFERENCES benchmark_cohorts(cohort_id), mode TEXT NOT NULL, trials INTEGER NOT NULL, solved INTEGER NOT NULL, par2_s REAL NOT NULL, measured_wall_s REAL, PRIMARY KEY (cohort_id, mode), CHECK (solved<=trials), CHECK (par2_s>=0));
CREATE TABLE IF NOT EXISTS benchmark_shard_progress (run_id INTEGER NOT NULL,shard INTEGER NOT NULL,mode TEXT NOT NULL,trials INTEGER NOT NULL,solved INTEGER NOT NULL,par2_s REAL NOT NULL,measured_elapsed_s REAL NOT NULL,source_url TEXT NOT NULL,status TEXT NOT NULL,PRIMARY KEY(run_id,shard,mode));
CREATE TABLE IF NOT EXISTS build_status (version TEXT PRIMARY KEY, branch TEXT NOT NULL, status TEXT NOT NULL, last_evidence_url TEXT NOT NULL, notes TEXT NOT NULL);

-- R174-BC: all 50 paired original-CNF case repetitions, finite time only on successful DRNAS; timeout baseline implies a lower bound only.
CREATE TABLE IF NOT EXISTS r174_bc_paired_cases (case_id TEXT NOT NULL, repeat_index INTEGER NOT NULL, cohort TEXT NOT NULL, bc_status TEXT NOT NULL, bc_elapsed_s REAL NOT NULL, clean_status TEXT NOT NULL, clean_elapsed_s REAL NOT NULL, r173_elapsed_s REAL NOT NULL, cap_s REAL NOT NULL, censored_speedup_lower_bound REAL, source_job_url TEXT NOT NULL, PRIMARY KEY (case_id,repeat_index));
CREATE TABLE IF NOT EXISTS r176_paired_original_cases (case_id TEXT NOT NULL, repeat_index INTEGER NOT NULL, mode TEXT NOT NULL, cohort TEXT NOT NULL, status TEXT NOT NULL, elapsed_s REAL NOT NULL, par2_s REAL NOT NULL, conflicts INTEGER NOT NULL, decisions INTEGER NOT NULL, feedback_consumed INTEGER NOT NULL, native_reason_clauses INTEGER NOT NULL, source_rows INTEGER NOT NULL, source_job_url TEXT NOT NULL, PRIMARY KEY(case_id,repeat_index,mode));
CREATE TABLE IF NOT EXISTS r177_paired_original_cases (case_id TEXT NOT NULL, repeat_index INTEGER NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL, elapsed_s REAL NOT NULL, par2_s REAL NOT NULL, conflicts INTEGER NOT NULL, decisions INTEGER NOT NULL, feedback_consumed INTEGER NOT NULL, reason_clauses INTEGER NOT NULL, onehop INTEGER NOT NULL, twohop INTEGER NOT NULL, proof_checks INTEGER NOT NULL, source_job_url TEXT NOT NULL, PRIMARY KEY(case_id,repeat_index,mode));
CREATE TABLE IF NOT EXISTS r178_baseline_difficulty_bands (band TEXT NOT NULL, mode TEXT NOT NULL, trials INTEGER NOT NULL, solved INTEGER NOT NULL, par2_s REAL NOT NULL, cohort_id TEXT NOT NULL, PRIMARY KEY(band,mode));
COMMIT;
