ON CONFLICT(cohort_id) DO UPDATE SET version=excluded.version,cohort_type=excluded.cohort_type,github_run_id=excluded.github_run_id,original_formulas=excluded.original_formulas,total_attempts=excluded.total_attempts,audit_status=excluded.audit_status,source_url=excluded.source_url,notes=excluded.notes;
