ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;


